# -*- coding: utf-8 -*-
from __future__ import annotations

import argparse
import sys
from pathlib import Path
from typing import Any


DEFAULT_PDF_NAME = "万華鏡30の分析結果.pdf"


def load_pdf_reader(pdf_path: Path) -> tuple[str, Any, Any]:
    """Return the first available PDF reader implementation."""
    errors: list[str] = []

    try:
        from pypdf import PdfReader  # type: ignore

        return "pypdf", PdfReader, None
    except Exception as exc:
        errors.append(f"pypdf: {exc}")

    try:
        from PyPDF2 import PdfReader  # type: ignore

        return "PyPDF2", PdfReader, None
    except Exception as exc:
        errors.append(f"PyPDF2: {exc}")

    message = (
        "Could not import pypdf or PyPDF2 in this Python environment.\n"
        + "\n".join(errors)
        + "\nTry: python -m pip install pypdf"
    )
    raise RuntimeError(message)


def extract_text(pdf_path: Path) -> tuple[str, list[str]]:
    library_name, pdf_reader, _ = load_pdf_reader(pdf_path)

    with pdf_path.open("rb") as file:
        try:
            reader = pdf_reader(file, strict=False)
        except TypeError:
            reader = pdf_reader(file)

        if getattr(reader, "is_encrypted", False):
            try:
                reader.decrypt("")
            except Exception as exc:
                raise RuntimeError(f"PDF is encrypted and could not be decrypted: {exc}") from exc

        pages_text: list[str] = []
        for index, page in enumerate(reader.pages, start=1):
            text = ""

            # pypdf supports layout mode in newer versions. PyPDF2 may not.
            try:
                text = page.extract_text(extraction_mode="layout") or ""
            except TypeError:
                text = page.extract_text() or ""
            except Exception:
                try:
                    text = page.extract_text() or ""
                except Exception as exc:
                    text = f"[Could not extract page {index}: {exc}]"

            pages_text.append(f"\n===== Page {index} =====\n{text.strip()}\n")

    return library_name, pages_text


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Extract text from a PDF using pypdf first, then PyPDF2."
    )
    parser.add_argument(
        "pdf",
        nargs="?",
        default=DEFAULT_PDF_NAME,
        help=f"PDF file path. Default: {DEFAULT_PDF_NAME}",
    )
    parser.add_argument(
        "-o",
        "--output",
        help="Output .txt path. Default: same PDF name with .txt extension.",
    )
    parser.add_argument(
        "--print",
        action="store_true",
        help="Also print extracted text to stdout.",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    pdf_path = Path(args.pdf)

    if not pdf_path.exists():
        print(f"PDF not found: {pdf_path}", file=sys.stderr)
        return 1

    output_path = Path(args.output) if args.output else pdf_path.with_suffix(".txt")

    try:
        library_name, pages_text = extract_text(pdf_path)
    except Exception as exc:
        print(str(exc), file=sys.stderr)
        return 1

    full_text = "".join(pages_text).strip() + "\n"
    output_path.write_text(full_text, encoding="utf-8")

    char_count = len(full_text.strip())
    print(f"Library: {library_name}")
    print(f"Pages: {len(pages_text)}")
    print(f"Characters: {char_count}")
    print(f"Output: {output_path}")

    if char_count == 0:
        print(
            "No text was extracted. The PDF may be scanned images or vectorized text.",
            file=sys.stderr,
        )
        return 2

    if args.print:
        try:
            print(full_text)
        except UnicodeEncodeError:
            print(
                "Extracted text was saved, but could not be printed with this console encoding.",
                file=sys.stderr,
            )

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

